.kpi {
  --destaque: #2563EB;
  --fonte-valor: 28px;
  position: absolute;
  inset: 3px 4px 6px 3px;
  box-sizing: border-box;
  padding: 12px 16px 10px 20px;
  background: #FFFFFF;
  border: 1px solid #E5E9F0;
  border-radius: 12px;
  box-shadow: 0 1px 2px rgba(27, 42, 74, 0.06), 0 4px 12px rgba(27, 42, 74, 0.08);
  overflow: hidden;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  color: #1B2A4A;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.kpi::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 4px;
  background: var(--destaque);
}
.kpi:hover {
  transform: translateY(-2px);
  box-shadow: 0 2px 4px rgba(27, 42, 74, 0.08), 0 10px 24px rgba(27, 42, 74, 0.14);
}
.kpi.animado {
  animation: kpi-entrada 0.5s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}
.kpi::after {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  left: -60%;
  width: 50%;
  background: linear-gradient(105deg, transparent 0%, rgba(255, 255, 255, 0.55) 50%, transparent 100%);
  transform: skewX(-12deg);
  pointer-events: none;
  opacity: 0;
}
.kpi.animado::after {
  animation: kpi-brilho 1.1s 0.55s ease-out both;
}
.kpi.escuro {
  background: radial-gradient(120% 140% at 100% 0%, rgba(34, 211, 238, 0.55) 0%, transparent 55%), linear-gradient(135deg, #1D4ED8 0%, #2563EB 45%, #0891B2 100%);
  border-color: rgba(255, 255, 255, 0.25);
  color: #FFFFFF;
  box-shadow: 0 0 0 1px rgba(34, 211, 238, 0.25), 0 8px 24px rgba(37, 99, 235, 0.45), 0 0 32px rgba(34, 211, 238, 0.25);
}
.kpi.escuro::before {
  background: #FFFFFF;
  opacity: 0.9;
}
.kpi.escuro::after {
  background: linear-gradient(105deg, transparent 0%, rgba(255, 255, 255, 0.35) 50%, transparent 100%);
}
.kpi.escuro:hover {
  box-shadow: 0 0 0 1px rgba(34, 211, 238, 0.4), 0 12px 32px rgba(37, 99, 235, 0.55), 0 0 44px rgba(34, 211, 238, 0.35);
}
.kpi.escuro .kpi-rotulo {
  color: rgba(255, 255, 255, 0.85);
}
.kpi.escuro .kpi-comparacao {
  color: rgba(255, 255, 255, 0.7);
}
.kpi.escuro .kpi-serie .ponto {
  border-color: #FFFFFF;
}
.kpi-cabecalho {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
}
.kpi-rotulo {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #64748B;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.kpi-valor {
  margin-top: 4px;
  font-size: var(--fonte-valor);
  font-weight: 600;
  line-height: 1.1;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  overflow: hidden;
  position: relative;
  z-index: 1;
}
.kpi-rodape {
  margin-top: 6px;
  display: flex;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
  position: relative;
  z-index: 1;
}
.kpi-pilula {
  display: inline-flex;
  align-items: center;
  padding: 2px 8px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}
.kpi-pilula.alerta {
  animation: kpi-alerta 1.2s 0.9s ease-out 2;
}
.kpi-comparacao {
  font-size: 10px;
  color: #94A3B8;
  white-space: nowrap;
  flex-shrink: 0;
}
.kpi-aviso {
  display: none;
  font-size: 11px;
  color: #64748B;
}
.kpi-serie {
  position: absolute;
  right: 14px;
  bottom: 10px;
  width: 40%;
  height: 30%;
}
.kpi-serie svg {
  display: block;
  width: 100%;
  height: 100%;
  overflow: visible;
}
.kpi-serie .linha {
  fill: none;
  stroke-width: 2;
  vector-effect: non-scaling-stroke;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: 1;
  stroke-dashoffset: 0;
}
.kpi-serie .ponto {
  position: absolute;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  border: 1.5px solid #FFFFFF;
  transform: translate(-50%, -50%);
  box-shadow: 0 0 0 0 var(--destaque);
}
.kpi-serie.desenhar .linha {
  animation: kpi-desenhar 1.1s 0.15s ease-out both;
}
.kpi-serie.desenhar .area {
  animation: kpi-aparecer 0.8s 0.5s ease-out both;
}
.kpi-serie.desenhar .ponto {
  animation: kpi-aparecer 0.3s 1.1s both, kpi-pulso 2.4s 1.4s ease-in-out infinite;
}
.kpi.compacto {
  padding-top: 8px;
}
.kpi.compacto .kpi-rodape {
  display: none;
}
@keyframes kpi-entrada {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
}
@keyframes kpi-desenhar {
  from {
    stroke-dashoffset: 1;
  }
  to {
    stroke-dashoffset: 0;
  }
}
@keyframes kpi-aparecer {
  from {
    opacity: 0;
  }
}
@keyframes kpi-brilho {
  0% {
    left: -60%;
    opacity: 1;
  }
  100% {
    left: 130%;
    opacity: 1;
  }
}
@keyframes kpi-alerta {
  0% {
    box-shadow: 0 0 0 0 color-mix(in srgb, var(--cor-pilula) 55%, transparent);
    transform: scale(1);
  }
  30% {
    transform: scale(1.08);
  }
  100% {
    box-shadow: 0 0 0 9px color-mix(in srgb, var(--cor-pilula) 0%, transparent);
    transform: scale(1);
  }
}
@keyframes kpi-pulso {
  0% {
    box-shadow: 0 0 0 0 color-mix(in srgb, var(--destaque) 45%, transparent);
  }
  70%,
  100% {
    box-shadow: 0 0 0 7px color-mix(in srgb, var(--destaque) 0%, transparent);
  }
}
@media (prefers-reduced-motion: reduce) {
  .kpi,
  .kpi * {
    animation: none !important;
    transition: none !important;
  }
}
